import itertools, json, os

def upsets(k):
    N=1<<k
    return [tuple((mask>>a)&1 for a in range(N)) for mask in range(1<<N) if all(not (mask>>a)&1 or (mask>>b)&1 for a in range(N) for b in range(N) if a&b==a)]

def construction(k):
    us=upsets(k); bits=range(1,(1<<k)-1)
    patterns=sorted(set(tuple(u[b] for b in bits) for u in us))
    orders=[]
    for i in range(k+2):
        def key(u):
            return tuple(u[j] if (i==0 or (i>=2 and b>>(i-2)&1)) else 1-u[j] for j,b in enumerate(bits))
        orders.append(sorted(range(len(patterns)),key=lambda a:key(patterns[a])))
    rank=[{a:j for j,a in enumerate(o)} for o in orders]
    n=len(patterns)
    for a in range(n):
        for b in range(n):
            if a==b:continue
            S={i for i in range(k+2) if rank[i][a]>rank[i][b]}
            assert S&{0,1} and S&set(range(2,k+2))
            for c in range(n):
                if c in (a,b):continue
                assert any(rank[i][a]>max(rank[i][b],rank[i][c]) for i in range(k+2))
    return us,patterns,rank

def check(k=3,m=2):
    us,pat,ranks=construction(k)
    n=len(pat); qs=[(a,) for a in range(n)]+list(itertools.combinations(range(n),2))
    points=[(x,y,A) for x in range(m) for y in range(m) for A in qs]
    vectors=[tuple((m*max(r[a] for a in A)+(x if i<2 else y)) for i,r in enumerate(ranks)) for x,y,A in points]
    # rank main coordinate scaled by m, exact finite lexicographic pairs
    for z,(x,y,A) in enumerate(points):
        for w,(u,v,B) in enumerate(points):
            actual=x<=u and y<=v and set(A)<=set(B)
            embedded=all(a<=b for a,b in zip(vectors[z],vectors[w]))
            assert actual==embedded,(points[z],points[w],vectors[z],vectors[w])
    inter=[u for u in us if all(a&b for a in range(1<<k) for b in range(1<<k) if u[a] and u[b])]
    print({'k':k,'Dedekind':len(us),'lambda(k+1)':len(inter),'patterns':n,'product_size':len(points),'ordered_pairs_checked':len(points)**2})
    assert len(pat)>=len(inter)+1

if __name__=='__main__':check()

